<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import NativeOperationStatus from './NativeOperationStatus.vue';
import {audioInput,nativeValue,gatewayStages,gatewayExtra,safeProviderUrl} from '../bot-native-data.js';
import {nativeReceipt} from '../bot-native-transport.js';
const props=defineProps({ui:{type:Object,required:true},bot:{type:Object,required:true},draft:{type:Object,required:true},enabled:Boolean,configBusy:Boolean});const emit=defineEmits(['save-config']);
const platform=ref(''),platformForm=ref({}),routeForm=ref({}),voices=ref({stt:{},tts:{}}),error=ref(''),message=ref({chatId:'',content:''}),speechText=ref(''),audio=ref(null),audioName=ref(''),preview=ref(''),recording=ref(false),starting=ref(false);
const gateway=computed(()=>props.ui.resource('gateway')),voice=computed(()=>props.ui.resource('voice')),gatewayValue=computed(()=>nativeValue(gateway.value.data)),voiceValue=computed(()=>nativeValue(voice.value.data));
const platforms=computed(()=>props.draft.config.gateway?.platforms||{}),routes=computed(()=>props.draft.config.gateway?.profileRoutes||[]);
const stages=computed(()=>gatewayStages(gateway.value.data,voiceValue.value));
const executable=computed(()=>props.enabled&&props.bot.control_state==='active'&&props.bot.config.permissions.mode==='execute'&&!props.ui.blocked());
const audioResults=computed(()=>{const data=nativeReceipt({result:voice.value.result})?.data;if(Array.isArray(data?.files))return data.files.filter(item=>item.mimeType?.startsWith('audio/')&&item.audioBase64).map(item=>({name:item.name,src:`data:${item.mimeType};base64,${item.audioBase64}`}));if(data?.audioBase64&&data?.mimeType?.startsWith('audio/'))return [{name:'合成音频',src:`data:${data.mimeType};base64,${data.audioBase64}`}];const item=data?.audio||data?.attachment;if(item?.contentEncoding==='base64'&&item.mimeType?.startsWith('audio/'))return [{name:item.name||'合成音频',src:`data:${item.mimeType};base64,${item.content}`}];return [];});
const speechOptions=ref({speed:1,instructions:''});
const transcript=computed(()=>nativeReceipt({result:voice.value.result})?.data?.transcript||nativeReceipt({result:voice.value.result})?.data?.text||'');
let generation=0,recorder=null,recordTimer=null,stream=null;
function cleanRecording(){clearTimeout(recordTimer);if(recorder&&recorder.state!=='inactive'){recorder.onstop=null;recorder.stop();}stream?.getTracks().forEach(track=>track.stop());stream=null;recorder=null;recording.value=false;starting.value=false;}
function clearAudio(){audio.value=null;audioName.value='';if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';}
function reset(){generation++;cleanRecording();clearAudio();platform.value='';platformForm.value={name:'',enabled:false,tokenEnv:'',allowedUsers:'',extra:'{}'};routeForm.value={name:'',platform:'',chat_id:'',thread_id:'',guild_id:'',enabled:true};voices.value={stt:{...(props.draft.config.voice?.stt||{})},tts:{...(props.draft.config.voice?.tts||{})}};error.value='';speechText.value='';speechOptions.value={speed:1,instructions:''};message.value={chatId:'',content:''};}
function editPlatform(name=''){const value=platforms.value[name]||{};platformForm.value={name,enabled:value.enabled===true,tokenEnv:value.tokenEnv||'',allowedUsers:(value.allowedUsers||[]).join('\n'),extra:JSON.stringify(value.extra||{},null,2)};platform.value=name;}
function addPlatform(){try{const form=platformForm.value,name=form.name.trim();if(!/^[a-z][a-z0-9_]{0,63}$/.test(name))throw new Error('请填写原生渠道标识');if(form.tokenEnv&&!/^[A-Z][A-Z0-9_]*$/.test(form.tokenEnv))throw new Error('凭据只填写本机环境变量名');const extra=gatewayExtra(JSON.parse(form.extra||'{}'));if(!extra||typeof extra!=='object'||Array.isArray(extra))throw new Error('高级设置须为 JSON 对象');props.draft.config.gateway||={platforms:{},profileRoutes:[]};props.draft.config.gateway.platforms[name]={enabled:form.enabled,...(form.tokenEnv?{tokenEnv:form.tokenEnv}:{}),allowedUsers:form.allowedUsers.split('\n').map(item=>item.trim()).filter(Boolean),extra};platform.value=name;error.value='';}catch(value){error.value=value.message;}}
function addRoute(){const row={...routeForm.value};if(!row.name||!row.platform)return;props.draft.config.gateway||={platforms:{},profileRoutes:[]};props.draft.config.gateway.profileRoutes.push(Object.fromEntries(Object.entries(row).filter(([,value])=>value!=='')));routeForm.value={name:'',platform:'',chat_id:'',thread_id:'',guild_id:'',enabled:true};}
function applyVoice(){try{const config={};for(const kind of ['stt','tts']){const row=voices.value[kind];if(!row.provider)continue;if(row.keyEnv&&!/^[A-Z][A-Z0-9_]*$/.test(row.keyEnv))throw new Error('音频凭据只填写本机环境变量名');if(row.baseUrl)safeProviderUrl(row.baseUrl);config[kind]=Object.fromEntries(Object.entries(row).filter(([,value])=>value!==''&&value!==undefined));}props.draft.config.voice=config;error.value='';}catch(value){error.value=value.message;}}
async function chooseAudio(file){const visit=generation;try{const value=await audioInput(file);if(visit!==generation)return;clearAudio();audio.value=value;audioName.value=file.name||'浏览器录音';preview.value=URL.createObjectURL(file);error.value='';}catch(value){if(visit===generation)error.value=value.message;}}
async function record(){if(starting.value)return;if(recording.value){recorder?.stop();return;}const visit=generation;starting.value=true;let acquired=null;try{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined')throw new Error('浏览器没有录音支持，可选择音频文件上传');acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(visit!==generation){acquired.getTracks().forEach(track=>track.stop());return;}const localStream=acquired,mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/webm'].find(value=>MediaRecorder.isTypeSupported(value)),localRecorder=new MediaRecorder(localStream,mime?{mimeType:mime}:{}),parts=[];stream=localStream;recorder=localRecorder;localRecorder.ondataavailable=event=>{if(event.data.size)parts.push(event.data);};localRecorder.onstop=async()=>{localStream.getTracks().forEach(track=>track.stop());if(visit!==generation)return;stream=null;recorder=null;recording.value=false;clearTimeout(recordTimer);await chooseAudio(new File(parts,'bot-recording.webm',{type:mime?.split(';')[0]||'audio/webm'}));};localRecorder.start();recording.value=true;recordTimer=setTimeout(()=>localRecorder.state!=='inactive'&&localRecorder.stop(),180000);error.value='';}catch(value){acquired?.getTracks().forEach(track=>track.stop());if(visit===generation){cleanRecording();error.value=value.message;}}finally{if(visit===generation)starting.value=false;}}
watch(()=>[props.ui.state.workspace,props.bot.id],reset,{immediate:true});onBeforeUnmount(()=>{generation++;cleanRecording();clearAudio();});
</script>
<template>
  <div class="native-workspace">
    <section class="native-section" aria-label="Gateway 渠道">
      <div class="native-toolbar"><div><h3>消息渠道 Gateway</h3><p class="native-help">配置渠道、授权引用与路由，分别核实保存、进程、渠道连接和媒体 provider。</p></div><button class="bot-button" :disabled="!enabled||gateway.loading" @click="ui.read('gateway')">读取连接状态</button></div>
      <div class="native-stage-grid"><article><strong>配置已保存</strong><span>{{bot.config.gateway?'已保存配置；需核对原生回读':'尚未保存渠道配置'}}</span></article><article><strong>Gateway 进程</strong><span>{{stages.process}}</span></article><article><strong>渠道连接</strong><span>{{stages.connection}}</span></article><article><strong>媒体 provider</strong><span>{{stages.media}}</span></article></div>
      <div class="native-list"><article v-for="(channel,name) in platforms" :key="name" class="native-list-row"><div><strong>{{name}}</strong><small>{{channel.enabled?'草稿中启用':'草稿中停用'}} · {{channel.tokenEnv?'已设置本机凭据引用':'凭据引用未配置'}}</small></div><button class="bot-button" @click="editPlatform(name)">编辑渠道</button></article></div>
      <div class="native-fields native-grid"><label>原生渠道标识<input v-model="platformForm.name" placeholder="原生已支持的平台名称"/></label><label>凭据环境变量名<input v-model="platformForm.tokenEnv" placeholder="MY_BOT_TOKEN"/></label><label class="inline-check wide"><input v-model="platformForm.enabled" type="checkbox"/>在配置中启用此渠道</label><label class="wide">允许的用户 ID（每行一个）<textarea v-model="platformForm.allowedUsers" rows="2"/></label><label class="wide">原生渠道高级设置 JSON<textarea v-model="platformForm.extra" rows="4" spellcheck="false"/></label></div><div class="native-actions"><button class="bot-button" :disabled="!enabled||configBusy" @click="addPlatform">加入渠道配置草稿</button></div>
      <details class="native-advanced"><summary>渠道会话路由</summary><div class="native-fields native-grid"><label>路由名称<input v-model="routeForm.name"/></label><label>渠道<select v-model="routeForm.platform"><option value="">选择渠道</option><option v-for="(_,name) in platforms" :key="name" :value="name">{{name}}</option></select></label><label>Chat ID<input v-model="routeForm.chat_id"/></label><label>Thread ID<input v-model="routeForm.thread_id"/></label><label>Guild ID<input v-model="routeForm.guild_id"/></label><label class="inline-check"><input v-model="routeForm.enabled" type="checkbox"/>启用路由</label></div><div class="native-actions"><button class="bot-button" :disabled="!enabled||configBusy" @click="addRoute">加入路由草稿</button></div><div class="native-list"><article v-for="(route,index) in routes" :key="index" class="native-list-row"><div><strong>{{route.name}}</strong><small>{{route.platform}} · {{route.chat_id||'未指定会话'}}</small></div><button class="bot-button danger" @click="draft.config.gateway.profileRoutes.splice(index,1)">移除路由</button></article></div></details>
      <div class="native-actions"><button class="bot-button primary" :disabled="!enabled||configBusy" @click="emit('save-config')">保存全部配置并读回</button><button class="bot-button" :disabled="!enabled||ui.blocked()||!bot.config.gateway" @click="ui.submit('gateway','configure',{config:bot.config.gateway})">同步已保存设置到原生</button></div>
      <div class="native-fields" style="margin-top:16px"><label>待控制渠道<select v-model="platform"><option value="">选择渠道</option><option v-for="(_,name) in platforms" :key="name" :value="name">{{name}}</option></select></label></div><div class="native-actions"><button class="bot-button" :disabled="!executable||!platform" @click="ui.submit('gateway','connect',{platform})">连接所选渠道</button><button class="bot-button" :disabled="!enabled||ui.blocked()||!platform" @click="ui.submit('gateway','disconnect',{platform})">断开所选渠道</button></div>
      <details class="native-advanced"><summary>向精确渠道会话发送</summary><div class="native-fields"><label>Chat ID<input v-model="message.chatId"/></label><label>消息正文<textarea v-model="message.content" rows="3"/></label></div><div class="native-actions"><button class="bot-button" :disabled="!executable||!platform||!message.chatId||!message.content.trim()" @click="ui.submit('gateway','outbound',{platform,chatId:message.chatId,content:message.content})">发送到此会话</button></div><p class="native-help">只使用明确填写的目标；结果未知时保留原请求，不生成新消息重发。</p></details><NativeOperationStatus :state="gateway" @poll="ui.poll('gateway')" @recover="ui.recover('gateway')"/>
    </section>
    <section class="native-section" aria-label="原生语音与音频">
      <div class="native-toolbar"><div><h3>语音与音频</h3><p class="native-help">浏览器录音或上传音频交给这位 Bot 的原生 STT；文本可交给原生 TTS。录音只在点击后使用浏览器麦克风。</p></div><button class="bot-button" :disabled="!enabled||voice.loading" @click="ui.read('voice')">读取音频依赖状态</button></div>
      <div class="native-grid"><div v-for="kind in ['stt','tts']" :key="kind" class="native-fields"><h4>{{kind==='stt'?'STT 语音转文字':'TTS 文字转语音'}}</h4><label>原生 provider<input v-model="voices[kind].provider"/></label><label>模型<input v-model="voices[kind].model"/></label><label>凭据环境变量名<input v-model="voices[kind].keyEnv"/></label><label>服务地址<input v-model="voices[kind].baseUrl" type="url"/></label><label>语言<input v-model="voices[kind].language"/></label><label v-if="kind==='tts'">声音<input v-model="voices[kind].voice"/></label><label class="inline-check"><input v-model="voices[kind].enabled" type="checkbox"/>启用此 provider</label></div></div><div class="native-actions"><button class="bot-button" :disabled="!enabled||configBusy" @click="applyVoice">加入音频配置草稿</button><button class="bot-button primary" :disabled="!enabled||configBusy" @click="emit('save-config')">保存全部配置并读回</button><button class="bot-button" :disabled="!enabled||ui.blocked()||!bot.config.voice" @click="ui.submit('voice','configure',{config:bot.config.voice})">同步已保存音频设置</button></div>
      <p v-if="voiceValue?.reason" class="native-help">{{voiceValue.reason}}</p><div class="native-fields" style="margin-top:18px"><label>音频文件<input type="file" accept="audio/*" :disabled="!enabled||recording||starting" @change="($event.target.files?.[0])&&chooseAudio($event.target.files[0])"/></label></div><div class="native-actions"><button class="bot-button" :disabled="!enabled||starting" @click="record">{{starting?'正在打开麦克风…':recording?'结束录音':'开始浏览器录音'}}</button><button class="bot-button" :disabled="!executable||!audio" @click="ui.submit('voice','transcribe',audio)">转写当前音频</button><button v-if="audio" class="bot-link" @click="clearAudio">移除音频</button></div><p class="native-help">{{audioName||'尚未选择音频'}} · 最多5 MiB，录音最多3分钟。解码和 provider 可用性以原生回执为准。</p><audio v-if="preview" class="native-audio" controls :src="preview"/>
      <div v-if="transcript" class="native-record">{{transcript}}</div><div class="native-fields"><label>要合成的文本<textarea v-model="speechText" rows="4"/></label></div><div class="native-fields native-grid"><label>语速<input v-model.number="speechOptions.speed" type="number" min="0.25" max="4" step="0.05"/></label><label>声音指导<input v-model="speechOptions.instructions" placeholder="由所选 provider 决定是否支持"/></label></div><div class="native-actions"><button class="bot-button" :disabled="!executable||!speechText.trim()" @click="ui.submit('voice','synthesize',{text:speechText,speed:speechOptions.speed,...(speechOptions.instructions?{instructions:speechOptions.instructions}:{}),...(bot.config.voice?.tts?.provider?{provider:bot.config.voice.tts.provider}:{})})">合成音频</button></div><div v-for="item in audioResults" :key="item.name"><p class="native-help">{{item.name}}</p><audio class="native-audio" controls :src="item.src"/></div><p v-if="error" role="alert" class="native-error">{{error}}</p><NativeOperationStatus :state="voice" @poll="ui.poll('voice')" @recover="ui.recover('voice')"/>
    </section>
  </div>
</template>
